import{i,s as t}from"./layout-YHxjb9E0.js";document.addEventListener("DOMContentLoaded",()=>{i();const n=document.getElementById("app-marina");n.innerHTML=t.getMarinas().map(e=>`<option value="${e.name}">${e.name}</option>`).join(""),document.getElementById("join-form").addEventListener("submit",e=>{e.preventDefault();const a=t.addApplication({name:document.getElementById("app-name").value.trim(),company:document.getElementById("app-company").value.trim(),email:document.getElementById("app-email").value.trim(),phone:document.getElementById("app-phone").value.trim(),marina:document.getElementById("app-marina").value,specialties:document.getElementById("app-specialty").value,vessel:document.getElementById("app-vessel").value.trim(),uscg:document.getElementById("app-uscg").value.trim(),note:document.getElementById("app-note").value.trim()});document.getElementById("join-result").innerHTML=`<div class="card" style="border-color:rgba(61,186,140,0.35)"><div class="card-kicker">Application received</div><h3>Reference ${a.id}</h3><p>Network review is invitation-first. We curate for guest experience — not volume. Expect a steward call within a few business days.</p></div>`,e.target.reset()})});
